#!/bin/bash
# Гейт 1298: реквизит гонки (шины, отбойники; msnart.c msnartDrawCull) — отсечение по кадру и выбор мешей по сетке 32 м.
#   tests/racecull1298/gate.sh DIR   DIR — набор с EBOOT.PBP и уровнем 2 (как для tools/smoke.sh). Сцена: L2, гонка с Милхаусом sr1 (flag msnmain 8), карточка, отсчёт, снимки r0 и r1.
# Пять прогонов (с 14.11 по умолчанию включена группировка непрозрачных по текстуре, слово Роба): 0 — прежний путь; 1 0 — отсечение без групп (порядок прежний, снимки равны эталону); 1 — по умолчанию (с группами): худший кадр ниже эталона, привязок текстуры меньше четверти мешей; красный к группам: при выключенных группах привязок = мешей (гейт «по умолчанию» краснеет). Четыре прогона безголовым эмулятором (строка RACEPROP раз в 60 кадров: мкс, меши, привязки, отсечено):
#   0  flag msnartcull1298 0 — прежний путь (эталон: картинка и счётчики);
#   1  по умолчанию — зелёный: мешей рисуется меньше, мкс меньше, отсечённых по кадру > 0, снимки r0 и r1 РАВНЫ эталону побайтно (md5; тот же EBOOT, прогоны подряд, у обоих быстрый ход);
#   3  со сверкой: у каждого отсечённого меша НИ ОДНА вершина не лежит внутри четырёх боковых плоскостей кадра (viol = 0); прогон медленный (3 мс на кадр на сверку), поэтому его снимки с эталоном не сравниваются;
#   4  красный контроль: радиус отсечения ×0,3 — сверка обязана дать viol > 0.
# Снимки зависят от времени кадра (мелкие анимации): сравнивать можно только прогоны одного EBOOT и одного хода; поэтому сравнение эталон/новое, а у сверки и красного — только счётчик viol.
set -u; cd "$(dirname "$0")/../.."; SRC="$1"; BAD=0
one() {   # режим [группа 0|1] [1 — память отсечения не выделяется] -> строка RACEPROP (последняя), md5 снимков, худший кадр
  local m=$1 g=${2:-} mf=${3:-} sc; sc=$(mktemp /tmp/rc.XXXXXX)
  { echo "flag nosave"; echo "flag golevel 2"; echo "wait 40"; echo "flag msn"; echo "wait 3"; echo "flag msnartcull1298 $m"; [ -n "$g" ] && echo "flag msnartgroup1298 $g"; [ -n "$mf" ] && echo "flag msnartcullmemfail 1"; echo "flag msnmain 8"; echo "wait 6"; echo "press cross 0.3"; echo "wait 5"; echo "press cross 0.3"; echo "wait 8"; echo "scene race0"; echo "shot r0"; echo "wait 3"; echo "shot r1"; echo "end"; } > "$sc"
  local R; R=$(SHIP_LEVELS="2 3 4 5 6 7" SMOKE_HEADLESS=1 SMOKE_BALLAST=5 SMOKE_MAXT=500 SMOKE_SCN="$sc" tools/smoke.sh "$SRC" 2>&1 | sed -n 's/^отчёт: \(.*\)\/summary\.txt.*/\1/p'); rm -f "$sc"
  case "$R" in /*) ;; *) R="$PWD/$R" ;; esac
  echo "$(grep -a '^RACEPROP' "$R/smoke.txt" | tail -1) r0=$(md5 -q "$R/r0.png" 2>/dev/null) r1=$(md5 -q "$R/r1.png" 2>/dev/null) wmax=$(grep -a -E '^race0' "$R/summary.txt" | awk '{print $8}')"
}
fld() { echo "$1" | sed -n "s/.* $2=\([^ ]*\).*/\1/p"; }
A=$(one 0); B=$(one 1 0); G=$(one 1); C=$(one 3); D=$(one 4); E=$(one 1 "" 1)
echo "эталон:   $A"; echo "без групп: $B"; echo "по умолчанию (группы): $G"; echo "сверка:   $C"; echo "красный:  $D"; echo "память не выделена: $E"
[ -n "$A" ] && [ "$(fld "$A" meshes)" -gt 0 ] 2>/dev/null || { echo "FAIL: эталон без реквизита (гейт пуст)"; BAD=1; }
[ "$(fld "$B" frustum_culled)" -gt 0 ] && [ "$(fld "$B" meshes)" -lt "$(fld "$A" meshes)" ] && [ "$(fld "$B" us)" -lt "$(fld "$A" us)" ] || { echo "FAIL: новое не рисует меньше / не быстрее"; BAD=1; }
# снимки и худший кадр (wmax) — справочно: зависят от времени кадра между запусками (эталон и отсечение без групп совпадали побайтно в двух запусках и расходились в третьем; худший кадр эталона 16,1–18,4 мс от запуска к запуску), условием гейта не служат; точность отсечения доказывает сверка вершин (viol=0)
echo "справочно: снимки эталон/без групп $([ "$(fld "$B" r0)" = "$(fld "$A" r0)" ] && [ "$(fld "$B" r1)" = "$(fld "$A" r1)" ] && echo равны || echo различаются); худший кадр эталон $(fld "$A" wmax), без групп $(fld "$B" wmax), по умолчанию $(fld "$G" wmax)"
# по умолчанию (группы): привязок не больше четверти мешей, мешей и мкс меньше эталона
[ "$(fld "$G" binds)" -le $(( $(fld "$G" meshes) / 4 )) ] 2>/dev/null || { echo "FAIL: группы по умолчанию не работают (привязок $(fld "$G" binds) из мешей $(fld "$G" meshes))"; BAD=1; }
[ "$(fld "$G" meshes)" -lt "$(fld "$A" meshes)" ] && [ "$(fld "$G" us)" -lt "$(fld "$A" us)" ] || { echo "FAIL: по умолчанию не рисует меньше / не быстрее эталона"; BAD=1; }
[ "$(fld "$B" binds)" = "$(fld "$B" meshes)" ] || { echo "FAIL: красный к группам: при выключенных группах привязок должно быть столько же, сколько мешей"; BAD=1; }
[ "$(fld "$C" viol)" = 0 ] && [ "$(fld "$C" frustum_culled)" -gt 0 ] || { echo "FAIL: сверка вершин: у отсечённого меша есть вершина внутри кадра"; BAD=1; }
[ "$(fld "$D" viol)" -ge 1 ] 2>/dev/null || { echo "FAIL: красный контроль не пойман"; BAD=1; }
# рабочая память отсечения (с 14.11 не статическая, 143 КБ BSS убраны): по умолчанию берётся из области «миссия» (~76 КБ), при отказе выделения — прежний путь без отсечения и без падения
[ "$(fld "$G" cullmem)" -gt 0 ] 2>/dev/null && [ "$(fld "$G" cullmem)" -lt 100000 ] || { echo "FAIL: память отсечения не выделена / больше 100 КБ ($(fld "$G" cullmem))"; BAD=1; }
[ "$(fld "$E" cullmem)" = 0 ] && [ "$(fld "$E" meshes)" = "$(fld "$A" meshes)" ] && [ "$(fld "$E" frustum_culled)" = 0 ] || { echo "FAIL: при отказе памяти должен идти прежний путь (мешей как у эталона, отсечённых 0)"; BAD=1; }
[ $BAD = 0 ] && echo PASS || echo FAIL; exit $BAD